def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')
    last_m, last_o = history[-1]
    if n < 10:
        if last_o == 'D':
            return 'D'
        return 'C'
    if n > 90:
        if opp_defects <= 2:
            return 'C'
    # Tit-for-tat with forgiveness early, then more retaliatory
    if last_o == 'C':
        return 'C'
    # Opponent defected
    if n < 30:
        # Analyze pattern: if opponent mostly cooperates, forgive occasionally
        if opp_defects <= max(1, n // 10):
            return 'C'
        return 'D'
    # Later: punish more aggressively if frequent defection
    if opp_defects > n * 0.3:
        return 'D'
    if opp_defects > n * 0.15:
        # stern but not permanent
        if last_m == 'D' and last_o == 'D':
            # check if we've been in a DD loop
            if n >= 2 and history[-2][1] == 'D':
                return 'C'
        return 'D'
    # opponent rarely defects - forgive quickly
    return 'C'
